// Before: it's not clear what it does
function x(a, b) { return a * 10 + (b ? 50 : 0); }
console.log(x(3, true));

// After: the same job, in a readable form
const STAR_POINTS = 10;
const BONUS_POINTS = 50;

function calculateScore(stars, hasBonus) {
  const bonus = hasBonus ? BONUS_POINTS : 0;
  return stars * STAR_POINTS + bonus;
}
console.log(calculateScore(3, true));

const pilot = { name: "Sam", level: 4, ship: "Eagle" };
const { name, ship } = pilot;
console.log(`${name} is on the ship ${ship}.`);

const [gold, silver] = ["Ada", "Ben", "Eve"];
console.log("First:", gold, "| Second:", silver);

function greet({ name, level = 1 }) {
  return `Hello ${name}, level ${level}`;
}
console.log(greet(pilot));
console.log(greet({ name: "Max" }));

