tasks.solution:
const MIN_FUEL = 50;

function canLaunch(ship) {
  if (!ship) return "No ship";
  const { fuel, crew } = ship;
  if (fuel < MIN_FUEL) return "Low fuel";
  if (crew <= 0) return "No crew";
  return "Launch!";
}

console.log(canLaunch({ fuel: 80, crew: 3 }));

